<script setup>
import { useAward } from './useAward.js';
import ChatScene from './components/ChatScene.vue';import MeetingScene from './components/MeetingScene.vue';import ReviewDesk from './components/ReviewDesk.vue';import CandidateForm from './components/CandidateForm.vue';import DefenseScene from './components/DefenseScene.vue';import DecisionScene from './components/DecisionScene.vue';import CeremonyScene from './components/CeremonyScene.vue';import EndScene from './components/EndScene.vue';
import { watch } from 'vue';import { recordStateChange } from './sessionRecorder.js';
const {state,opened,page,modal,scale,draft,player,school,candidates,selectedCandidates,current,winner,openedCandidate,act,go,advance,receive,openForm,front,move,drop,tidy,startDefense,answer,nextCandidate,chooseWinner,confirmWinner,settings,saveSettings,reset,fullscreen}=useAward();
const chapters=['一 · 开会','二 · 审阅','三 · 答辩','四 · 颁奖'];
watch(state, recordStateChange, { deep: true });
</script>
<template><div id="viewport"><main id="game" aria-label="颁什么奖游戏原型" :data-scene="state.scene" :style="{transform:`scale(${scale})`}"><header id="header"><div class="logo"><em>颁</em>什么<em>奖</em></div><div class="serial">ANY AWARD / 试点·001</div><nav class="chapters" aria-label="当前章节"><span v-for="(chapter,i) in chapters" :key="chapter" :class="{active:i===act}">{{ chapter }}</span></nav></header><section id="stage">
<ChatScene v-if="state.scene==='chat'" :player="player" @receive="receive" />
<MeetingScene v-else-if="state.scene==='meeting'" :line="state.line" :player="player" @next="advance" />
<ReviewDesk v-else-if="state.scene==='review'" :candidates="candidates" :positions="state.positions" :selected="state.selected" :scale="scale" @move="move" @front="front" @drop="drop" @open="openForm" @tidy="tidy" @submit="startDefense" />
<DefenseScene v-else-if="state.scene==='defense' && current" :candidate="current" :index="state.defenseIndex" :step="state.defenseStep" @inspect="openForm" @answer="answer" @next="nextCandidate" />
<DecisionScene v-else-if="state.scene==='decision'" :candidates="selectedCandidates" :winner="state.winner" :player="player" @inspect="openForm" @choose="chooseWinner" @back="go('review')" @confirm="confirmWinner" />
<CeremonyScene v-else-if="state.scene==='ceremony' && winner" :candidate="winner" :school="school" :player="player" @handover="go('end')" />
<EndScene v-else-if="state.scene==='end' && winner" :candidate="winner" :candidates="selectedCandidates" :player="player" @review="go('review')" @restart="modal='restart'" />
</section><footer id="footer"><span>奖励执行委员会　／　{{ player }}　　<span class="mono">2026</span>年度 · 有志少年奖</span><div class="foot-tools"><span>Vue 3 · 本地固定剧本 · 自动保存</span><button class="small" data-action="settings" @click="settings">名称设置</button><button class="small" data-action="fullscreen" @click="fullscreen">全屏</button><button class="small" data-action="restart" @click="modal='restart'">重新开始</button></div></footer><div id="overlay">
<CandidateForm v-if="openedCandidate" :key="opened" :candidate="openedCandidate" :page="page" :selected="state.selected.includes(opened)" :selected-count="state.selected.length" :review="state.scene==='review'" :school="school" :player="player" @close="opened=null" @flip="page=1-page" />
<div v-if="modal" class="overlay-back" role="dialog" aria-modal="true" :aria-label="modal==='settings'?'名称设置':'重新开始'"><form v-if="modal==='settings'" class="confirm-box" @submit.prevent="saveSettings"><h2>名称设置</h2><p>修改称呼，不改变当前评选进度。校名留空时显示“本校”。</p><label>玩家称呼<input id="player-name" v-model="draft.playerName" maxlength="16"></label><label>学校名称<input id="school-name" v-model="draft.schoolName" maxlength="24" placeholder="本校"></label><div class="actions"><button type="button" data-action="cancel-restart" @click="modal=''">取消</button><button class="primary" data-action="save-settings" type="submit">保存设置</button></div></form><div v-else class="confirm-box"><h2>重新开始本次评选？</h2><p>当前名单、审阅记录、桌面位置与名称设置将清除。</p><div class="actions"><button data-action="cancel-restart" @click="modal=''">取消</button><button class="primary" data-action="reset" @click="reset">清除并重新开始</button></div></div></div>
</div></main></div></template>
